'use strict';

// MODULES //

var resolve = require( '@stdlib/utils/json-pointer/resolve' );


// MAIN //

/**
* Retrieves the value at a specified JSON Pointer from a document.
*
* ## Notes
*
* -   Implements retrieval per RFC 6901.
* -   An empty string pointer refers to the root of the document.
*
* @param {(Object|Array)} document - JSON document
* @param {string} pointer - JSON Pointer string
* @throws {TypeError} first argument must be an object or array
* @throws {TypeError} second argument must be a string
* @throws {Error} pointer must resolve to an existing location in the document
* @throws {Error} tokens must not be prototype pollution vectors
* @throws {RangeError} array index must be within bounds
* @returns {*} value at the specified location
*
* @example
* var out = get( { 'foo': [ 'bar', 'baz' ] }, '/foo/0' );
* // returns 'bar'
*
* @example
* var out = get( { 'foo': 'bar' }, '/foo' );
* // returns 'bar'
*
* @example
* var out = get( { 'foo': 'bar' }, '' );
* // returns { 'foo': 'bar' }
*/
function get( document, pointer ) {
	return resolve( document, pointer ).value;
}


// EXPORTS //

module.exports = get;
